import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const realm={rosterText:fs.readFileSync('docs/demos/live-game-roster-v62.json','utf8'),referenceText:fs.readFileSync('docs/demos/live-public-ability-reference-v1.json','utf8')};
vm.runInNewContext(fs.readFileSync('dist/batting-workbench-core.js','utf8'),realm);
vm.runInNewContext(`
 const core=KneekuraBaseballWorkbench,roster=JSON.parse(rosterText),reference=JSON.parse(referenceText),playerId='0-b0';
 const project=r=>core.projectLivePublicAbilitiesV1({roster:r,reference,playerId}).abilities;
 const initial=project(roster),entry=roster.entries.find(e=>e.playerId===playerId);
 const after=core.setLiveTraitProfileV1({roster,playerId,familyId:'throw_accuracy',stateId:'A'}).roster;
 const advanced=core.setLiveTraitProfileV1({roster,playerId,familyId:'advanced_fielding',stateId:'MASTERED',source:{effectScale:2}}).roster;
 globalThis.audit={playerId,throwBefore:entry.physical.throwDirectionStdRadians,throwAfter:after.entries.find(e=>e.playerId===playerId).physical.throwDirectionStdRadians,
  publicBefore:initial.find(a=>a.id==='throwingAccuracy').value,publicAfter:project(after).find(a=>a.id==='throwingAccuracy').value,
  throwProfileBefore:entry.traitProfile??null,throwProfileAfter:after.entries.find(e=>e.playerId===playerId).traitProfile??null,
  newTechniquePublicUnchanged:JSON.stringify(project(advanced))===JSON.stringify(initial),newTechniquePhysicalUnchanged:JSON.stringify(advanced.entries.map(e=>e.physical))===JSON.stringify(roster.entries.map(e=>e.physical))};
`,realm);
assert.notEqual(realm.audit.throwBefore,realm.audit.throwAfter);
assert(realm.audit.publicAfter>realm.audit.publicBefore);
assert(realm.audit.newTechniquePublicUnchanged&&realm.audit.newTechniquePhysicalUnchanged);
console.log(JSON.stringify({auditCompleted:true,observedUnwantedBaseMutation:true,...realm.audit}));
